mapper.insert:
/* apiDefReg.savApiCtgry */
SELECT CURRVAL('koa_tb_api_ctgry_api_ctgry_no_seq')
INSERT INTO KOA_TB_API_CTGRY ( API_SPC_NO ,CTGRY_NM ,SORT_ODRG ,DEL_YN ,REG_DT ,REGR ,AMD_DT ,AMDR ) VALUES ( #{apiSpcNo}::integer ,#{ctgryNm} ,1 ,'N' ,NOW() ,#{regr} ,NOW() ,#{amdr} )

/* apiDefReg.savApiDef */

  SELECT CURRVAL('koa_tb_api_def_api_no_seq')

INSERT INTO KOA_TB_API_DEF
(
   API_SPC_NO
  ,API_ID
  ,API_VER
  ,API_VER_NO
  ,API_NM
  ,API_CTGRY_NO
  ,API_PATH
  ,METHOD_CD
  ,API_DESC
  ,REG_DT
  ,REGR
  ,AMD_DT
  ,AMDR
  ,USE_YN
  ,GUIDE_GUBUN
  ,SANDBOX_YN
  ,API_GUBUN
  ,API_HANDLER_CD
  ,PROVIDER_SEQ
  ,ENDPNT_METHOD_CD
  ,ENDPNT_TB_URL
  ,ENDPNT_PRD_URL
  ,ENDPNT_CLIENT_IP
  ,ENDPNT_TIMEOUT
  ,RESMAP_RES_CD_FIELD
  ,RESMAP_SUCC_VAL
  ,RESMAP_ERR_CD_FIELD
  ,RESMAP_ERR_MSG_FIELD
  ,HDP_API_ENDPOINT_ID
  ,HDP_REQ_API_NAME
  ,HDP_API_OUT_FORMAT
  ,HDP_API_OUT_COMMON_PARAM
  ,HDP_REQ_MAPPING_TO_BODY
  ,HDP_RES_MAPPING_TO_BODY
  ,HDP_REQ_CONFIG_TO_BODY
  ,HDP_REQ_HEADER_TO_BODY
  ,HDP_RES_PROVIDE_PARAM
  ,HDP_REQ_URL_DECODE
  ,HDP_REQ_URL_ENCODE
  ,HDP_RES_URL_ENCODE
  ,HDP_HNDLROPTN_CONFIG
  ,HDP_EXT_PROP
  ,BSTGW_TB_SYS_ID
  ,BSTGW_PRD_SYS_ID
)
VALUES
(
   #{apiSpcNo}::integer
  ,#{apiId}
  ,NULLIF(#{apiVer}, '')
  ,COALESCE(NULLIF(#{apiVerNo}, '')::integer, 0)
  ,#{apiNm}
  ,#{apiCtgryNo}::integer
  ,#{apiPath}
  ,#{methodCd}
  ,#{apiDesc}
  ,NOW()
  ,#{regr}
  ,NOW()
  ,#{amdr}
  ,COALESCE(NULLIF(#{useYn}, ''), 'Y')
  ,NULLIF(#{guideGubun}, '')
  ,COALESCE(NULLIF(#{sandboxYn}, ''), 'N')
  ,#{apiClass}
  ,NULLIF(#{apiHandlerCd}, '')
  ,NULLIF(#{providerSeq}, '')::integer
  ,NULLIF(#{endpntMethodCd}, '')
  ,#{endpntTbUrl}
  ,#{endpntPrdUrl}
  ,#{endpntClientIp}
  ,NULLIF(#{endpntTimeout}, '')::integer
  ,#{resmapResCdField}
  ,#{resmapSuccVal}
  ,#{resmapErrCdField}
  ,#{resmapErrMsgField}
  ,#{hdpApiEndpointId}
  ,#{hdpReqApiName}
  ,#{hdpApiOutFormat}
  ,#{hdpApiOutCommonParam}
  ,#{hdpReqMappingToBody}
  ,#{hdpResMappingToBody}
  ,#{hdpReqConfigToBody}
  ,#{hdpReqHeaderToBody}
  ,#{hdpResProvideParam}
  ,#{hdpReqUrlDecode}
  ,#{hdpReqUrlEncode}
  ,#{hdpResUrlEncode}
  ,#{hdpHndlroptnConfig}
  ,#{hdpExtProp}
  ,NULLIF(#{bstgwTbSysId}, '')
  ,NULLIF(#{bstgwPrdSysId}, '')
)

mapper.select:
/* apiDefReg.selApiIdChk */ SELECT COUNT(API_NO) FROM KOA_TB_API_DEF WHERE API_ID = REPLACE(#{apiId}, ' ', '')
AND API_NO != #{apiNo}::integer
AND API_VER_NO != #{apiVerNo}::integer

mapper.update:
/* apiDefReg.updApiDef */
UPDATE KOA_TB_API_DEF
SET
   API_ID                    = #{apiId}
  ,API_VER                   = NULLIF(#{apiVer}, '')
  ,API_NM                    = #{apiNm}
  ,API_PATH                  = #{apiPath}
  ,METHOD_CD                 = #{methodCd}
  ,API_DESC                  = #{apiDesc}
  ,USE_YN                    = COALESCE(NULLIF(#{useYn}, ''), 'Y')
  ,GUIDE_GUBUN                = NULLIF(#{guideGubun}, '')
  ,SANDBOX_YN                = COALESCE(NULLIF(#{sandboxYn}, ''), 'N')
  ,API_GUBUN                 = #{apiClass}
  ,API_HANDLER_CD            = NULLIF(#{apiHandlerCd}, '')
  ,PROVIDER_SEQ              = NULLIF(#{providerSeq}, '')::integer
  ,ENDPNT_METHOD_CD          = NULLIF(#{endpntMethodCd}, '')
  ,ENDPNT_TB_URL             = #{endpntTbUrl}
  ,ENDPNT_PRD_URL            = #{endpntPrdUrl}
  ,ENDPNT_CLIENT_IP          = #{endpntClientIp}
  ,ENDPNT_TIMEOUT            = NULLIF(#{endpntTimeout}, '')::integer
  ,RESMAP_RES_CD_FIELD       = #{resmapResCdField}
  ,RESMAP_SUCC_VAL           = #{resmapSuccVal}
  ,RESMAP_ERR_CD_FIELD       = #{resmapErrCdField}
  ,RESMAP_ERR_MSG_FIELD      = #{resmapErrMsgField}
  ,HDP_API_ENDPOINT_ID       = #{hdpApiEndpointId}
  ,HDP_REQ_API_NAME          = #{hdpReqApiName}
  ,HDP_API_OUT_FORMAT        = #{hdpApiOutFormat}
  ,HDP_API_OUT_COMMON_PARAM  = #{hdpApiOutCommonParam}
  ,HDP_REQ_MAPPING_TO_BODY   = #{hdpReqMappingToBody}
  ,HDP_RES_MAPPING_TO_BODY   = #{hdpResMappingToBody}
  ,HDP_REQ_CONFIG_TO_BODY    = #{hdpReqConfigToBody}
  ,HDP_REQ_HEADER_TO_BODY    = #{hdpReqHeaderToBody}
  ,HDP_RES_PROVIDE_PARAM     = #{hdpResProvideParam}
  ,HDP_REQ_URL_DECODE        = #{hdpReqUrlDecode}
  ,HDP_REQ_URL_ENCODE        = #{hdpReqUrlEncode}
  ,HDP_RES_URL_ENCODE        = #{hdpResUrlEncode}
  ,HDP_HNDLROPTN_CONFIG      = #{hdpHndlroptnConfig}
  ,HDP_EXT_PROP              = #{hdpExtProp}
  ,BSTGW_TB_SYS_ID           = NULLIF(#{bstgwTbSysId}, '')
  ,BSTGW_PRD_SYS_ID          = NULLIF(#{bstgwPrdSysId}, '')
  ,AMD_DT                    = NOW()
  ,AMDR                      = #{amdr}
WHERE API_NO = #{apiNo}::integer

mapper.insert:
/* apiDefReg.savApiParam */
SELECT CURRVAL('koa_tb_api_param_param_no_seq')
INSERT INTO KOA_TB_API_PARAM ( API_NO ,PARAM_TYPE_CD ,SORT_ODRG ,PARAM_NM ,DATA_TYPE_CD ,PARAM_DESC ,PARAM_LOC ,REQUIRED ,PRNTS_PARAM_NO ,OBJ_NO ,OBJ_ODRG ,EXAM ,PERSONAL_DATA ,DO_NOT_SEND ,FIXED_VALUE ,HIDDEN ,MAPPING_KEY ,BIGO ,PARAM_SANDBOX_YN ,HDP_URL_DECODE ,HDP_URL_ENCODE ,HDP_UPLOAD_TARGET ,RES_CD ,RES_DESC ,REG_DT ,REGR ,AMD_DT ,AMDR ) VALUES ( #{apiNo}::integer ,#{paramTypeCd} ,#{sortOdrg}::integer ,#{paramNm} ,#{dataTypeCd} ,#{paramDesc} ,#{paramLoc} ,#{required} ,NULLIF(#{prntsParamNo}, '')::integer ,NULLIF(#{objNo}, '')::integer ,NULLIF(#{objOdrg}, '')::integer ,#{exam} ,#{personalData} ,NULLIF(#{doNotSend}, '') ,NULLIF(#{fixedValue}, '') ,NULLIF(#{hidden}, '') ,NULLIF(#{mappingKey}, '') ,NULLIF(#{bigo}, '') ,NULLIF(#{paramSandboxYn}, '') ,NULLIF(#{hdpUrlDecode}, '') ,NULLIF(#{hdpUrlEncode}, '') ,NULLIF(#{hdpUploadTarget}, '') ,NULLIF(#{resCd}, '') ,NULLIF(#{resDesc}, '') ,NOW() ,#{regr} ,NOW() ,#{regr} )
